from attrs import define, frozen, field

@define(frozen=True)
class Money:
    cents: int
    currency: str = "EUR"

    @field(validator=...)  # optional validators
    def cents(self, value):
        if value < 0:
            raise ValueError("cents must be non-negative")
        return value

m = Money(cents=1999)
