from pypersistent import PersistentDict, persistent

m = PersistentDict.create(name="Alice", age=30)
m2 = m.set('city', 'NYC')          # m unchanged; m2 has all 3 keys
m3 = m | {'role': 'developer'}     # merge syntax; both original and merged share structure

# Functional update with a wither-like method
@persistent
class Person:
    def __init__(self, name, age):
        self._data = PersistentDict.create(name=name, age=age)
    def with_age(self, new_age):
        return Person(self._data['name'], new_age)
